
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_edmgga_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_edmgga", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.384346813271719e+00, -3.371978601416297e+00, -3.361104546662185e+00, -3.352110159880967e+00, -3.327574829541124e+00, -3.231338432993887e+00, -3.003865285031823e+00, -2.643215381238403e+00, -2.194290870914130e+00, -1.717111949042762e+00, -1.207849996476196e+00, -7.257060165137287e-01, -5.809738778352078e-01, -5.037411439319264e-01, -3.904653857894546e-01, -2.765586209359320e-01, -1.837938242798342e-01, -1.146772873515551e-01, -7.165272865320206e-02, -4.756478753391622e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


